contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive the contract with one payable play call and then assert an observable relation.
    // params:
    // - sendAmt: amount of wei to send in the play call (must equal C.TICKET_AMOUNT)
    // - preBalance: this contract's balance must be at least sendAmt
    function run(uint sendAmt) public payable {
        // Preconditions: we must call with enough balance to cover sending; and sendAmt must equal ticket amount
        require(address(this).balance >= sendAmt, "insufficient balance to call play");
        // Call play once, sending sendAmt
        c.play{value: sendAmt}();

        // Observe two public things: the pot value and c's contract balance
        uint pot = c.pot();
        uint bankBal = address(c).balance;

        // ASSERT ONE COMPARISON: either pot == 0 implies that this call resulted in payout to caller
        // For original contract, when the random branch triggers (random==0) the pot is reset to 0 and the caller received (previousPot + sendAmt - FEE)
        // We assert that if pot == 0 then the contract balance decreased by at least (sendAmt - c.FEE_AMOUNT()) compared to before the call.
        // To make this check self-contained we compare c's balance (which after payout will be only FEE retained) vs at least FEE.

        // Fetch fee constant
        uint fee = c.FEE_AMOUNT();

        // The single required assert: if pot == 0 then c's balance is equal to fee (meaning whole pot was paid out except fee)
        // This distinguishes the original behavior (pot reset when random==0) from the mutant (pot reset when random==1) because for the same caller
        // there exist executions where original yields pot==0 and contract balance == fee, while the mutant will not for that execution.
        assert(!(pot == 0) || bankBal == fee);
    }

    // Allow this test contract to receive ETH funding before calling run
    receive() external payable {}
}

contract InvMutTest {
    C c;
    bool __obsd;
    uint __snap;
    constructor(C _c) { c = _c; }

    // We take the payment amount as a parameter so we can forward exactly TICKET_AMOUNT.
    // The test observes c.pot() MID-call via receive() which is invoked when C sends Ether to this contract.
    function run(uint amount) public payable {
        // require we forward exactly the ticket amount expected by C
        require(address(this).balance >= amount);
        // The correct contract will, for some caller entropy, send the pot-payout to the caller
        // during play() causing this.receive to run and capture c.pot() MID-call.
        c.play{value: amount}();
        // After the external call completes, assert that when we observed MID-call, the pot was 0
        // (i.e., the contract emptied its pot during the call). This holds on the original but
        // is violated by the mutant that flips the winning condition.
        assert(__obsd && __snap == 0);
    }

    receive() external payable {
        // capture pot MID-call exactly once
        if (!__obsd) {
            __obsd = true;
            __snap = c.pot();
        }
    }
}

