pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint constant TICKET = 10;

    function setUp() public { c = new C(); }

    // fuzz the caller address and a block timestamp offset to influence the pseudo-random
    function testFuzz_property(address caller, uint256 tsOffset) public {
        // keep caller as a non-zero EOA and limit tsOffset to a reasonable range
        vm.assume(caller != address(0));
        tsOffset = bound(tsOffset, 0, 1000);

        // Fund caller and set environment so keccak entropy (block.timestamp) can vary
        vm.deal(caller, 1 ether);

        // warp the block timestamp to a value influenced by the fuzzer
        vm.warp(block.timestamp + int256(tsOffset));

        // perform the payable call from the fuzzed caller with the exact ticket amount
        vm.prank(caller);
        c.play{value: TICKET}();

        // The universal property we assert: after any admissible play call with correct ticket
        // amount, the pot is either zero (if the reference's random indicates a win) or
        // equal to the ticket amount (if no win happened because pot started at 0 and
        // only this ticket was added). Concretely, for the reference contract starting
        // from pot==0, after one play the pot must be either 0 or TICKET.
        // The mutant flips the winning condition so for some inputs the mutant will
        // produce the opposite outcome; thus this assertion will fail on the mutant
        // for those inputs.
        uint256 p = c.pot();
        assertTrue(p == 0 || p == TICKET);
    }
}

