contract InvMutTest {
    C public c;

    constructor(C _c) { c = _c; }

    // Drive the contract: send one ticket then trigger the winning branch by calling play normally.
    // We cannot force randomness; instead we express the property conditionally using revert observation:
    // We require that calling play with ticketAmount succeeds and that afterward address(c).balance == FEE_AMOUNT.
    // The test takes ticketAmount and feeAmount as inputs (must match C's constants) and an amount to send.

    function run(uint ticketAmount, uint feeAmount, uint sendAmount) public payable {
        // ensure this contract has enough balance to forward
        require(address(this).balance >= sendAmount, "insufficient balance");
        require(sendAmount == ticketAmount, "must send exactly ticketAmount");

        // Make the play call that may change pot and balances
        c.play{value: sendAmount}();

        // After a winning resolution in the original contract, the contract balance equals feeAmount.
        // This is the distinguishing assertion: P pays out the pot and leaves only the fee in contract balance.
        assert(address(c).balance == feeAmount);
    }

    // Allow the test contract to receive ETH for forwarding
    receive() external payable {}
}

