import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address and a block timestamp offset to vary randomness
    function testFuzz_property(address caller, uint256 timeOffset) public {
        // admissible domain: caller must be a non-zero address
        vm.assume(caller != address(0));
        // keep timeOffset reasonably bounded to avoid weird warp overflow
        timeOffset = bound(timeOffset, 0, 1 days);

        // Arrange: give caller enough ETH and record pot before
        uint256 ticket = 10; // must match C.TICKET_AMOUNT
        vm.deal(caller, ticket);
        uint256 before = c.pot();

        // Move time so randomness can vary (and be influenced by fuzzed timeOffset)
        vm.warp(block.timestamp + timeOffset);

        // Act: caller calls play() sending exactly the ticket amount
        bool ok;
        vm.prank(caller);
        try c.play{value: ticket}() {
            ok = true;
        } catch {
            // If call reverts, treat as failure of call (but reference shouldn't revert for valid input)
            ok = false;
        }

        // Observed property on reference: after a successful call that accepted the ticket,
        // pot must have increased by at least the ticket amount (pot_after >= pot_before).
        // We assert that whenever the call did NOT revert, pot_after >= pot_before.
        uint256 after = c.pot();

        // Single assertion reading c that the correct contract always satisfies and the mutant breaks
        // (mutant that omitted pot increment can leave pot unchanged, violating pot_after >= pot_before).
        if (ok) {
            assertTrue(after >= before, "pot did not increase on successful play");
        } else {
            // If the call reverted, still assert the property vacuously by comparing equal (this path
            // should not occur for the reference under admissible inputs); we assert true to satisfy
            // the single assertion requirement by mapping revert to a true condition on c.
            // However we must still issue exactly one assertTrue reading c: compare pot equality.
            assertTrue(after >= before, "pot did not increase on reverted play");
        }
    }
}

