import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: actor address and a block timestamp offset to influence randomness
    function testFuzz_property(address actor, uint64 timeOffset) public {
        // keep actor non-zero
        vm.assume(actor != address(0));

        // ensure the ticket amount is exactly what contract expects
        uint256 ticket = 10;
        // fund actor
        vm.deal(actor, 1 ether);

        // snapshot pre-call global funds (contract balance + pot)
        uint256 pre_total = address(c).balance + c.pot();

        // manipulate block.timestamp slightly (keep wide bounds)
        // bound timeOffset to a reasonable window to avoid unrealistic warp values
        uint64 boundedOffset = uint64(bound(timeOffset, 0, 1 days));
        vm.warp(block.timestamp + boundedOffset);

        // make the call as actor sending exactly ticket
        vm.prank(actor);
        // we call without trying to force a particular random bit; we will detect only when a payout occurred
        (bool ok,) = address(c).call{value: ticket}(abi.encodeWithSignature("play()"));
        // call should not revert on either contract (reference handles normally)
        // record post-call totals
        uint256 post_total = address(c).balance + c.pot();

        // If a payout occurred the reference C always transfers only the fee out of the system,
        // so post_total should equal pre_total - FEE_AMOUNT. If no payout, post_total == pre_total + ticket.
        // We cannot observe the random bit directly, but we can assert a universal invariant that when
        // a payout happened (detected by a decrease in total funds), the decrease equals exactly 1 (FEE_AMOUNT).

        // compute delta with underflow-safe arithmetic
        if (post_total < pre_total) {
            // payout branch detected
            assertTrue(pre_total - post_total == 1);
        } else {
            // no payout: total must have increased by exactly the ticket amount
            assertTrue(post_total - pre_total == ticket);
        }
    }
}

