pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address to let the fuzzer pick an EOA that we will fund and use
    function testFuzz_property(address player) public {
        // keep player non-zero to be admissible
        vm.assume(player != address(0));

        // fund the player so they can send the ticket
        uint256 ticket = 10;
        vm.deal(player, ticket);

        // We need to force the random branch (random == 0) to execute to observe pot reset behavior.
        // Since randomness uses block.timestamp, block.difficulty, msg.sender, we can control msg.sender
        // by using vm.prank(player). The fuzzer cannot directly control block.timestamp; instead we
        // rely on the probabilistic nature of the fuzzer trying many inputs — but to make this reliable
        // we will loop multiple attempts in the same test invocation to increase chance of hitting the
        // branch within a single fuzzed input. This still keeps the test property universal: for any
        // player, whenever the reference contract's winning branch executes the pot must be 0 afterwards.

        // Attempt multiple plays until either we observe pot==0 after play or we exhaust attempts.
        bool sawZero = false;
        // limit attempts to keep test bounded
        for (uint i = 0; i < 8; i++) {
            vm.prank(player);
            // call play with the exact ticket amount
            try c.play{value: ticket}() {
                // after call completes, check pot getter
                uint p = c.pot();
                if (p == 0) {
                    sawZero = true;
                    break;
                }
            } catch {
                // ignore reverts here; continue attempts
            }
            // advance timestamp to change randomness for next attempt
            vm.warp(block.timestamp + 1);
        }

        // The universal property we assert: for any admissible player, if any play() completed and
        // resulted in the winning branch, reference contract's pot must be 0. We implement this by
        // asserting that at least one of the attempts resulted in pot==0. The mutant that changes
        // the fee transfer amount can cause intermediate observable differences that prevent pot
        // from being observed as 0 after completion in some scenarios; the fuzzer will find such
        // a player/timing causing the mutant to fail this assertion.
        assertTrue(sawZero);
    }
}

// No adversarial helper contract is necessary because the difference is observable via the
// reference contract's public pot getter after play() completes; we vary msg.sender and timestamp
// to trigger the random branch.

