import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: attacker address (as EOA seed) and a boolean to choose whether attacker will reenter
    function testFuzz_property(address attackerSeed, bool willReenter) public {
        // keep attackerSeed non-zero
        vm.assume(attackerSeed != address(0));

        // We need an adversarial counterparty that can re-enter when receiving funds.
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // fund attacker so it can pay ticket
        uint256 TICKET = 10;
        vm.deal(address(attacker), TICKET);

        // ensure caller has exactly TICKET to send
        if (!willReenter) {
            // If not reentering, set attacker to a benign one that does not reenter
            attacker.setReenter(false);
        } else {
            attacker.setReenter(true);
        }

        // perform the call from attacker
        // attacker will call c.play{value: TICKET}()
        // Use try/catch to ensure we observe successful completion; but the property we check is pot==0
        bool ok;
        try attacker.doPlay{value: TICKET}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: after play() returns, the correct contract always has pot == 0
        // We assert that pot == 0. The mutant allowing reentrancy to exploit fee=0 will make this fail for some inputs.
        assertTrue(ok == true && c.pot() == 0);
    }
}

// Minimal adversarial helper that can optionally reenter during its receive
contract ReentrantAttacker {
    address public target;
    bool public reenter;

    constructor(address _target) payable {
        target = _target;
        reenter = true;
    }

    function setReenter(bool r) public {
        reenter = r;
    }

    // called by test to perform the play call
    function doPlay() public payable {
        // forward the exact ticket amount to target.play
        (bool success, ) = target.call{value: msg.value}(abi.encodeWithSignature("play()"));
        require(success);
    }

    // when receiving funds, optionally reenter into target.play to attempt to exploit intermediate state
    receive() external payable {
        if (reenter) {
            // try to reenter with 0 value (can't send more), just call play to observe/interact
            // Protect from infinite recursion: only attempt reentry once by setting reenter=false
            reenter = false;
            // attempt to call play (will revert due to wrong value usually); ignore revert
            (bool ok, ) = target.call(abi.encodeWithSignature("play()"));
            // swallow ok
            ok;
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: send an amount and assert relation between pot and whether the call reverted
    function run(uint256 sendAmount) public payable {
        // require this test caller has enough balance to forward the amount
        require(address(this).balance >= sendAmount, "insufficient balance to forward");

        // record pot before
        uint256 potBefore = c.pot();

        // attempt to call play forwarding sendAmount; capture whether it reverted
        bool didRevert;
        // low-level call to detect revert without bubbling
        (bool ok, ) = address(c).call{value: sendAmount}(abi.encodeWithSignature("play()"));
        didRevert = !ok;

        // read pot after
        uint256 potAfter = c.pot();

        // The distinguishing rule: if the sent amount equals C.TICKET_AMOUNT then the call must revert and pot must remain equal.
        // Expressed as: (sendAmount == TICKET_AMOUNT) => (didRevert && potAfter == potBefore)
        // We cannot access C.TICKET_AMOUNT constant directly, so require behavior for the specific value 10 as in the original contract.
        // Use a general rule: when sendAmount equals 10, the call reverts and pot is unchanged.
        assert(!(sendAmount == 10) || (didRevert && potAfter == potBefore));
    }

    // allow contract to receive ETH so tests can forward funds
    receive() external payable {}
}

