contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address so the fuzzer can find cases where randomness branch does not drain the pot
    function testFuzz_property(address caller) public {
        // keep caller in the admissible domain (non-zero)
        vm.assume(caller != address(0));
        // ensure caller has funds to buy a ticket
        uint256 ticket = 10; // matches contract constant TICKET_AMOUNT
        vm.deal(caller, ticket);

        // snapshot pot before
        uint256 potBefore = c.pot();

        // make the call as the fuzzed caller paying exactly the ticket amount
        vm.prank(caller);
        c.play{value: ticket}();

        // After a play call where msg.value == TICKET_AMOUNT, the correct contract always increases pot by msg.value
        // (unless the contract paid out and reset pot to zero in the same call, but that only happens when random==0;
        // however in that case the net effect before transfer of fee is that pot was incremented by msg.value first,
        // and then possibly set to zero — importantly, immediately after the call completes the pot is either
        // potBefore + msg.value (if no payout) or 0 (if payout). The mutant that only adds FEE_AMOUNT can leave pot == potBefore + FEE_AMOUNT,
        // which for many inputs is neither potBefore + msg.value nor 0.)

        // The universal property we assert here is that potAfter is either potBefore + ticket OR 0.
        // The buggy mutant can produce potBefore + FEE_AMOUNT which for ticket!=FEE_AMOUNT will violate this.
        uint256 potAfter = c.pot();

        bool ok = (potAfter == potBefore + ticket) || (potAfter == 0);
        assertTrue(ok);
    }
}
